<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue';
import { RouterLink, useRoute, useRouter } from 'vue-router';
import { PhArrowLeft, PhArrowClockwise, PhArrowRight, PhChatCircle, PhCheck, PhPlus, PhPlugsConnected, PhShieldCheck } from '@phosphor-icons/vue';
import { runtimeStateLabels, type PlatformConfig, type PlatformType, type PlatformsResponseSchema, type RuntimeConfig } from '../../../../typescript/packages/contracts/src/index';
import { confirmDestructiveAction, useUnsavedDraft } from '../../composables/unsaved';
import { randomId } from '../../utils/random-id';
import PlatformConnectionEditor from './PlatformConnectionEditor.vue';
import { senderScopeLabel } from './sender-authorization';
import { createPlatformDraft, platformConfigurationIssues, platformLabels, platformRouteSummary, platformIssueText, preparePlatformConnection } from './platform-workbench';
const config = defineModel<RuntimeConfig>({ required: true });
const props = withDefaults(defineProps<{ publishedPlatforms?: readonly PlatformConfig[]; statuses?: ReturnType<typeof PlatformsResponseSchema.parse>['platforms']; busy?: boolean; selectedId?: string }>(), { publishedPlatforms: () => [], statuses: () => [], busy: false });
const emit = defineEmits<{ refresh: []; select: [id: string]; 'open-capabilities': [platformId: string, type: PlatformType] }>();
const route = useRoute(); const router = useRouter();
type DetailTab = 'connection' | 'messages' | 'routing' | 'capabilities';
type WizardStep = 1 | 2 | 3 | 4;
const detailTabs: { id: DetailTab; label: string }[] = [{ id: 'connection', label: '连接设置' }, { id: 'messages', label: '消息与响应' }, { id: 'routing', label: '处理规则' }, { id: 'capabilities', label: '平台能力' }];
const platformTypes: readonly PlatformType[] = ['napcat', 'telegram', 'weixin'];
const platformDescriptions: Readonly<Record<PlatformType, string>> = { napcat: 'QQ · OneBot v11', telegram: 'Telegram · Bot API', weixin: '微信 · iLink' };
const statusLabels = { disabled: '未启用', starting: '连接中', connected: '已连接', error: '连接异常', stopped: '已停止' };
const selectedIndex = ref(0); const missingId = ref(''); const detailTab = ref<DetailTab>('connection'); const notice = ref(''); const issues = ref<string[]>([]);
const selected = computed(() => missingId.value ? undefined : config.value.platforms[selectedIndex.value]);
const published = computed(() => props.publishedPlatforms.find(item => item.id === selected.value?.id));
const pending = computed(() => !!selected.value && JSON.stringify(selected.value) !== JSON.stringify(published.value));
const selectedStatus = computed(() => props.statuses.find(item => item.id === selected.value?.id));
const selectedGrants = computed(() => config.value.grants.filter(item => item.platform === selected.value?.id));
const selectedRules = computed(() => config.value.flow.routing.rules.filter(item => item.platform === selected.value?.id));
const groupPolicyLabel = computed(() => config.value.flow.acceptance.groupPolicy === 'mention_or_reply' ? '提及或回复机器人时处理' : config.value.flow.acceptance.groupPolicy === 'all' ? '处理所有群消息' : '不处理群消息');
const defaultAgentName = computed(() => config.value.agents.find(item => item.id === config.value.flow.routing.defaultAgentId)?.displayName ?? config.value.flow.routing.defaultAgentId);
const wizardHeading = ref<HTMLElement>();
const wizard = ref<PlatformConfig>(); const wizardStep = ref<WizardStep>(1); const wizardAgent = ref(''); const validationSignature = ref('');
const wizardDraft = useUnsavedDraft('机器人接入向导', () => wizard.value ? { platform: wizard.value, agent: wizardAgent.value } : null, '/platforms');
const configurationChecked = computed(() => !!wizard.value && validationSignature.value === JSON.stringify(wizard.value));
const selectedSignature = computed(() => JSON.stringify(selected.value));
const checkedSelectedSignature = ref('');
watch(wizardStep, () => { void nextTick(() => wizardHeading.value?.focus()); });
function clearWizard(): void { wizard.value = undefined; wizardAgent.value = ''; wizardStep.value = 1; validationSignature.value = ''; wizardDraft.markSaved(); }
function applySelection(id?: string): void { const index = id ? config.value.platforms.findIndex(item => item.id === id) : 0; missingId.value = id && index < 0 ? id : ''; selectedIndex.value = Math.max(0, index); detailTab.value = 'connection'; issues.value = []; notice.value = ''; checkedSelectedSignature.value = ''; }
watch(() => route.query.platform, value => { if (route.path !== '/platforms') return; clearWizard(); applySelection(typeof value === 'string' ? value : props.selectedId); }, { immediate: true });
watch(() => props.selectedId, value => { if (!value || !wizardDraft.confirmDiscard()) return; clearWizard(); applySelection(value); });
watch(() => config.value.platforms, () => { const id = typeof route.query.platform === 'string' ? route.query.platform : props.selectedId; applySelection(id); });
async function choose(id: string): Promise<void> {
  if (props.busy) return;
  if (route.query.platform === id) { if (!wizardDraft.confirmDiscard()) return; clearWizard(); applySelection(id); }
  else { const failure = await router.push({ path: '/platforms', query: { ...route.query, platform: id } }); if (failure) return; }
  emit('select', id);
}
function statusFor(item: PlatformConfig): string { if (!props.publishedPlatforms.some(value => value.id === item.id)) return '尚未发布'; const status = props.statuses.find(value => value.id === item.id); return status ? statusLabels[status.status] : '状态未获取'; }
function isConnected(item: PlatformConfig): boolean { return props.publishedPlatforms.some(value => value.id === item.id) && props.statuses.some(value => value.id === item.id && value.status === 'connected'); }
function openWizard(): void { if (props.busy || !wizardDraft.confirmDiscard()) return; wizard.value = createPlatformDraft('napcat', randomId().slice(0, 8)); wizardAgent.value = ''; wizardStep.value = 1; issues.value = []; notice.value = ''; validationSignature.value = ''; wizardDraft.markSaved(); void nextTick(() => wizardHeading.value?.focus()); }
function cancelWizard(): void { if (!wizardDraft.confirmDiscard()) return; clearWizard(); issues.value = []; }
function changeWizardPlatform(type: PlatformType): void { if (!wizard.value || wizard.value.type === type) return; const name = wizard.value.displayName; const previousDefault = `我的 ${platformLabels[wizard.value.type]} 机器人`; wizard.value = createPlatformDraft(type, randomId().slice(0, 8)); if (name !== previousDefault) wizard.value.displayName = name; validationSignature.value = ''; issues.value = []; }
function validateWizard(): boolean { const item = wizard.value; if (!item) return false; issues.value = platformConfigurationIssues(item, config.value.platforms); if (!issues.value.length) validationSignature.value = JSON.stringify(item); return !issues.value.length; }
function validateSelected(): void { const item = selected.value; if (!item) return; issues.value = platformConfigurationIssues(item, config.value.platforms.filter((_item, index) => index !== selectedIndex.value)); checkedSelectedSignature.value = issues.value.length ? '' : selectedSignature.value; }
function back(): void { if (wizardStep.value === 1) cancelWizard(); else if (wizardStep.value === 2) wizardStep.value = 1; else if (wizardStep.value === 3) wizardStep.value = 2; else wizardStep.value = 3; issues.value = []; }
async function next(): Promise<void> {
  const item = wizard.value; if (!item || props.busy) return;
  issues.value = [];
  if (wizardStep.value === 1) { if (!item.displayName.trim()) { issues.value = [platformIssueText.name]; return; } wizardStep.value = 2; return; }
  if (wizardStep.value === 2) { if (validateWizard()) wizardStep.value = 3; return; }
  if (wizardAgent.value && !config.value.agents.some(agent => agent.id === wizardAgent.value && agent.enabled)) { issues.value = [platformIssueText.agent]; return; }
  if (wizardAgent.value && config.value.flow.routing.rules.length >= 100) { issues.value = [platformIssueText.rules]; return; }
  if (wizardStep.value === 3) { wizardStep.value = 4; return; }
  if (!validateWizard()) return;
  const prepared = preparePlatformConnection(config.value, item, wizardAgent.value, randomId().slice(0, 8));
  if (!prepared.ok) { issues.value = prepared.issues; return; }
  config.value = prepared.config;
  clearWizard(); selectedIndex.value = config.value.platforms.length - 1; missingId.value = '';
  const failure = await router.push({ path: '/platforms', query: { ...route.query, platform: prepared.platformId } });
  if (!failure) emit('select', prepared.platformId);
  notice.value = `“${item.displayName}”已加入配置草稿。请发布配置。${item.type === 'weixin' ? '然后扫码登录。' : ''}点击“刷新状态”读取连接状态。`;
}
function updateSelected(value: PlatformConfig): void { if (selected.value) config.value.platforms[selectedIndex.value] = value; }
async function identityChanged(id: string): Promise<void> { if (!id || config.value.platforms.filter(item => item.id === id).length > 1) { issues.value = [id ? platformIssueText.duplicateId : platformIssueText.id]; return; } const failure = await router.replace({ path: '/platforms', query: { ...route.query, platform: id } }); if (!failure) emit('select', id); }
function remove(): void {
  const item = selected.value; if (!item) return;
  const related = selectedRules.value.length + selectedGrants.value.length;
  if (!confirmDestructiveAction(`从配置草稿移除“${item.displayName || item.id}”？发布后会断开此机器人。${related ? `另有 ${related} 条路由或发送者授权引用此实例。请到对应页面修改这些引用。` : ''}`)) return;
  config.value.platforms.splice(selectedIndex.value, 1); selectedIndex.value = Math.min(selectedIndex.value, Math.max(0, config.value.platforms.length - 1));
  const nextItem = config.value.platforms[selectedIndex.value]; missingId.value = '';
  void router.replace({ path: '/platforms', query: { ...route.query, platform: nextItem?.id } }); notice.value = '机器人已从配置草稿移除。发布配置后断开连接。';
}
function setEmojis(event: Event): void { if (selected.value?.type !== 'napcat' || !(event.target instanceof HTMLTextAreaElement)) return; selected.value.preAckEmoji.emojis = event.target.value.split('\n').map(value => value.trim()).filter(Boolean); }
</script>
<template>
<section class="platform-workbench" aria-label="机器人工作空间">
  <header class="workbench-heading"><div><h2>{{ wizard ? '接入机器人' : '已接入的机器人' }}</h2><p>管理机器人连接和消息处理规则。</p></div><div v-if="!wizard" class="heading-actions"><button :disabled="busy" @click="emit('refresh')"><PhArrowClockwise :size="17"/>刷新状态</button><button class="primary" :disabled="busy" @click="openWizard"><PhPlus :size="17"/>接入机器人</button></div></header>
  <p v-if="notice" class="workbench-notice" role="status">{{notice}}</p>
  <div v-if="issues.length" class="workbench-error" role="alert"><strong>请修正以下字段</strong><ul><li v-for="issue in issues" :key="issue">{{issue}}</li></ul></div>
  <section v-if="wizard" class="platform-wizard">
    <ol class="wizard-steps" aria-label="接入步骤"><li v-for="(label,index) in ['选择平台','填写连接','处理规则','确认接入']" :key="label" :aria-current="wizardStep===index+1?'step':undefined" :class="{complete:wizardStep>index+1}"><span><PhCheck v-if="wizardStep>index+1" :size="14"/><template v-else>{{index+1}}</template></span>{{label}}</li></ol>
    <fieldset :disabled="busy" class="wizard-content">
      <template v-if="wizardStep===1"><h3 ref="wizardHeading" tabindex="-1">选择接入平台</h3><p class="muted">同一套 Agent 可以同时连接多个机器人。</p><div class="platform-choices"><button v-for="type in platformTypes" :key="type" type="button" :aria-pressed="wizard.type===type" @click="changeWizardPlatform(type)"><PhPlugsConnected :size="23"/><strong>{{platformLabels[type]}}</strong><small>{{platformDescriptions[type]}}</small></button></div><label>机器人名称<input v-model="wizard.displayName" maxlength="120" placeholder="例如：我的 QQ 助手"></label><details><summary>自定义实例 ID</summary><label>实例 ID<input v-model="wizard.id" autocomplete="off"><small>用于关联路由、授权和日志。填写一个未使用的 ID。</small></label></details></template>
      <template v-else-if="wizardStep===2"><h3 ref="wizardHeading" tabindex="-1">连接 {{platformLabels[wizard.type]}}</h3><p class="muted">本步只检查填写格式。发布配置后，再读取连接状态。</p><PlatformConnectionEditor v-model="wizard" :identity="false" :disabled="busy"/><div class="inline-actions"><button type="button" @click="validateWizard">检查配置格式</button><span v-if="configurationChecked" class="validation-result" role="status"><PhCheck :size="16"/>格式检查通过。尚未检查凭据和连接。</span></div></template>
      <template v-else-if="wizardStep===3"><h3 ref="wizardHeading" tabindex="-1">决定如何处理消息</h3><label>目标 Agent<select v-model="wizardAgent"><option value="">沿用全局路由（默认 {{defaultAgentName}}）</option><option v-for="agent in config.agents.filter(item=>item.enabled)" :key="agent.id" :value="agent.id">{{agent.displayName}}</option></select><small v-if="wizardAgent">将创建此实例的专用规则。该规则排在现有规则之前。</small><small v-else>按顺序匹配现有规则。未命中时使用默认 Agent。</small></label><div class="rules-summary"><div><span>群聊触发</span><strong>{{groupPolicyLabel}}</strong></div><div><span>私聊处理</span><strong>{{config.flow.acceptance.privateEnabled?'开启':'关闭'}}</strong></div><div><span>会话白名单</span><strong>{{config.flow.acceptance.allowlist.enabled?'已开启。请在路由中添加此实例的允许会话。':'未启用全局白名单'}}</strong></div><div><span>运行态</span><strong>按发送者授权确定</strong></div></div><p class="workbench-notice">此实例沿用全局触发规则和权限设置。接入机器人不会授予管理权限。需要限制群或发送者时，请配置路由和授权。</p><div class="inline-actions"><RouterLink to="/flow">查看全局消息路由 <PhArrowRight :size="15"/></RouterLink><RouterLink to="/permissions">管理发送者授权 <PhArrowRight :size="15"/></RouterLink></div></template>
      <template v-else><h3 ref="wizardHeading" tabindex="-1">确认加入配置草稿</h3><div class="rules-summary"><div><span>机器人</span><strong>{{wizard.displayName}} · {{platformLabels[wizard.type]}}</strong></div><div><span>实例 ID</span><strong>{{wizard.id}}</strong></div><div><span>目标 Agent</span><strong>{{wizardAgent ? config.agents.find(item=>item.id===wizardAgent)?.displayName : `沿用全局路由 · 默认 ${defaultAgentName}`}}</strong></div><div><span>群聊触发</span><strong>{{groupPolicyLabel}}</strong></div><div><span>凭据</span><strong>{{wizard.type==='napcat'?wizard.accessTokenEnv:wizard.tokenEnv}}（服务器环境变量名）</strong></div></div><label class="check-row"><input v-model="wizard.enabled" type="checkbox">发布配置后启用此机器人</label><p class="workbench-notice">下一步将机器人加入配置草稿。请在页面顶部发布配置。<template v-if="wizard.type==='weixin'">然后扫码登录。</template>点击“刷新状态”读取连接状态。</p></template>
    </fieldset>
    <footer class="wizard-footer"><button :disabled="busy" @click="back"><PhArrowLeft :size="16"/>{{wizardStep===1?'取消接入':'上一步'}}</button><span>{{wizardStep}} / 4</span><button class="primary" :disabled="busy" @click="next">{{wizardStep===4?'加入配置草稿':wizardStep===2?'检查并继续':'下一步'}}<PhArrowRight :size="16"/></button></footer>
  </section>
  <div v-else class="platform-layout">
    <aside class="platform-list" aria-label="机器人实例"><p class="list-label">我的机器人 <span>{{config.platforms.length}}</span></p><button v-for="item in config.platforms" :key="item.id" :disabled="busy" :class="{selected:selected===item}" @click="choose(item.id)"><div><span class="connection-dot" :class="{online:isConnected(item)}"></span><strong>{{item.displayName || item.id}}</strong></div><small>{{platformDescriptions[item.type]}}</small><span class="instance-status">{{statusFor(item)}}</span></button><p v-if="!config.platforms.length" class="muted list-empty">尚未接入机器人。点击“接入机器人”开始。</p></aside>
    <section v-if="selected" class="platform-detail">
      <header class="detail-heading"><div><p class="eyebrow">{{platformDescriptions[selected.type]}}</p><h3>{{selected.displayName || selected.id}}</h3><small>{{selected.id}}</small></div><label class="check-row"><input v-model="selected.enabled" type="checkbox" :disabled="busy">启用机器人</label></header>
      <div class="connection-status"><span class="connection-dot" :class="{online:isConnected(selected)}"></span><strong>{{statusFor(selected)}}</strong><span v-if="pending" class="pending-tag">{{published?'有待发布修改':'新增草稿'}}</span><small>启停和连接设置在发布配置后生效。</small><p v-if="selectedStatus?.message && published" :class="{error:selectedStatus.status==='error'}">{{selectedStatus.message}}</p><p v-if="published" class="status-note">这是已发布配置的连接状态。</p></div>
      <nav class="detail-tabs" aria-label="机器人设置"><button v-for="tab in detailTabs" :key="tab.id" :aria-current="detailTab===tab.id?'page':undefined" @click="detailTab=tab.id">{{tab.label}}</button></nav>
      <div class="detail-body">
        <template v-if="detailTab==='connection'"><PlatformConnectionEditor :model-value="selected" @update:model-value="updateSelected" :disabled="busy" @identity-change="identityChanged"/><div class="inline-actions"><button :disabled="busy" @click="validateSelected">检查配置格式</button><span v-if="checkedSelectedSignature && checkedSelectedSignature===selectedSignature" class="validation-result" role="status"><PhCheck :size="16"/>格式检查通过。发布配置后，点击“刷新状态”读取连接状态。</span></div><div v-if="selected.type==='weixin'" class="login-section"><slot name="platform-login" :platform="selected"><p class="muted">发布配置后，请生成二维码并扫码登录。</p></slot></div><details class="remove-section"><summary>移除机器人</summary><p class="muted">此操作从配置草稿移除机器人。发布配置后断开连接。历史会话和执行记录保留。</p><button class="danger" :disabled="busy" @click="remove">移除机器人配置</button></details></template>
        <template v-else-if="detailTab==='messages'"><template v-if="selected.type==='napcat'"><section class="form-section"><div class="section-icon"><PhChatCircle :size="22"/><h4>消息防刷屏</h4></div><label>合并转发字数阈值<input v-model.number="selected.forwardThreshold" type="number" min="0" max="200000" step="1" :disabled="busy"><small>回复超过此字数时，发送为一条合并转发。填写 0 关闭。群聊和私聊均适用。</small></label><p class="muted">文字和图片合为一条图文消息。文件单独上传。</p></section><section class="form-section"><h4>开始处理表情</h4><label class="check-row"><input v-model="selected.preAckEmoji.enabled" type="checkbox" :disabled="busy">开始处理时给触发消息贴表情</label><label>表情列表（每行一个，最多 32 个）<textarea :value="selected.preAckEmoji.emojis.join('\n')" :disabled="busy || !selected.preAckEmoji.enabled" rows="4" placeholder="124&#10;👀&#10;🤔" @change="setEmojis"></textarea><small>填写 QQ 表情数字 ID 或单个 Unicode 表情，例如 124 或 👀。留空不贴表情。</small></label><p class="muted">仅群聊生效。任务开始时随机选择一个表情。排队时不贴。完成后保留。</p><details><summary>表情兼容说明</summary><p class="muted">QQ 表情示例：124（OK）、76（赞）、66（爱心）。不支持多人、肤色和旗帜等组合表情。贴表情失败不影响回复。修改后，到“连接设置”检查配置格式。</p></details></section></template><template v-else><h4>回复投递</h4><p class="muted">此平台使用全局回复投递设置。在消息路由中配置流式发送、发送间隔和失败回退。</p><RouterLink class="text-link" to="/flow">配置消息处理与投递 <PhArrowRight :size="16"/></RouterLink></template></template>
        <template v-else-if="detailTab==='routing'"><h4>一套全局消息路由</h4><div class="flow-summary"><span>平台消息</span><PhArrowRight :size="14"/><span>触发检查</span><PhArrowRight :size="14"/><span>权限检查</span><PhArrowRight :size="14"/><span>Agent</span><PhArrowRight :size="14"/><span>回复</span></div><div class="rules-summary"><div><span>Agent 分配</span><strong>{{platformRouteSummary(config,selected.id)}}</strong></div><div><span>群聊触发</span><strong>{{groupPolicyLabel}}</strong></div><div><span>私聊处理</span><strong>{{config.flow.acceptance.privateEnabled?'开启':'关闭'}}</strong></div><div><span>实例白名单条目</span><strong>{{config.flow.acceptance.allowlist.enabled ? `${config.flow.acceptance.allowlist.entries.filter(item=>item.platform===selected?.id).length} 条（全局白名单已开启）` : '未启用全局白名单'}}</strong></div><div><span>发送者授权</span><strong>{{selectedGrants.length}} 条 · {{new Set(selectedGrants.flatMap(grant=>grant.senderIds)).size}} 个发送者</strong></div></div><p class="muted">当前显示配置草稿。系统按顺序匹配路由。未命中规则时使用默认 Agent。服务器按平台、会话和发送者检查权限。</p><div v-if="selectedGrants.length" class="grant-summary"><div v-for="(grant,index) in selectedGrants" :key="index"><PhShieldCheck :size="16"/><span>{{grant.senderIds.join('、')}} · {{senderScopeLabel(grant)}} · {{runtimeStateLabels[grant.state]}}</span></div></div><div class="inline-actions"><RouterLink :to="{path:'/flow',query:{platform:selected.id}}">编辑路由与触发规则 <PhArrowRight :size="16"/></RouterLink><RouterLink :to="{path:'/permissions',query:{platform:selected.id}}">管理发送者授权 <PhArrowRight :size="16"/></RouterLink><RouterLink to="/agents">管理 Agent <PhArrowRight :size="16"/></RouterLink></div></template>
        <template v-else><h4>{{platformLabels[selected.type]}} 平台能力</h4><p class="muted">平台能力用于处理此平台的消息、附件和会话。先配置平台工具。再为 Agent 选择工具。最后设置发送者授权。</p><div class="capability-entry"><PhPlugsConnected :size="26"/><div><strong>查看平台工具与配置</strong><small>查看已接入的平台工具，修改工具配置。</small></div><button :disabled="busy" @click="emit('open-capabilities',selected.id,selected.type)">管理能力 <PhArrowRight :size="16"/></button></div><p class="muted">新增机器人不会自动授予工具或管理权限。</p><RouterLink class="text-link" to="/agents">为 Agent 装配能力 <PhArrowRight :size="16"/></RouterLink></template>
      </div>
    </section>
    <section v-else class="platform-empty"><PhPlugsConnected :size="42"/><h3>{{missingId?'未找到这个机器人':'连接你的第一个机器人'}}</h3><p>{{missingId?`当前草稿中没有实例 ${missingId}。请选择左侧已有机器人，或重新接入。`:'接入 NapCat、Telegram 或微信，让 Agent 在常用聊天平台中工作。'}}</p><button class="primary" :disabled="busy" @click="openWizard"><PhPlus :size="17"/>接入机器人</button></section>
  </div>
</section>
</template>
<style scoped>
